    ValidatePlayerStatArray(root, contextPrefix, issues, "statsDecreased");
    ValidateSetCharacteristics(root, contextPrefix, issues);
    ValidatePlayerSkillChanges(root, contextPrefix, issues, "activeSkillChanges");
