    [InlineData("{\"unspentStatPoints\":-1,\"levelUpStatPointsAwardedThroughLevel\":1}")]
    [InlineData("{\"unspentStatPoints\":0,\"levelUpStatPointsAwardedThroughLevel\":\"1\"}")]
